{"policy":"permit (
    principal is Requester,
    action == Action::"readTelemetry",
    resource is TelemetryRecord
)
when {
    (principal.roles.contains(Role::"Operator") ||
     principal.roles.contains(Role::"FleetAdmin")) &&
    principal in resource.device.siteGroup &&
    (principal == resource.device.owner ||
     principal.clearance >= resource.sensitivity)
};

forbid (
    principal is Requester,
    action == Action::"readTelemetry",
    resource is TelemetryRecord
)
when {
    (principal.roles.contains(Role::"Operator") ||
     principal.roles.contains(Role::"FleetAdmin")) &&
    !(principal in resource.device.siteGroup)
};"}
